#include <iostream>
#include <vector>
#include <algorithm>

typedef long long LL;

int solve(LL number, int pos, const std::vector<LL>& puteri)
{
    LL contor = number / puteri[pos];
    if (number % puteri[pos] == 0)
        return static_cast<int>(pos * contor);
    int a = pos * contor + solve(number % puteri[pos], pos - 1, puteri);
    int b = pos * (contor + 1) + solve(puteri[pos] - (number % puteri[pos]), pos - 1, puteri);
    return std::min(a, b);
}

int main()
{
    std::vector<LL> puteri(20);
    puteri[1] = 1;
    for (int i = 2; i <= 17; ++i)
        puteri[i] = puteri[i - 1] * 10LL + 1;
    LL n;
    std::cin >> n;
    std::cout << solve(n, 17, puteri);
    return 0;
}
